\item If $X$ is Kolmogorov then so is $Y$.
\item Suppose $Y$ is locally closed in $X$. If $X$ is quasi-sober then
so is $Y$.
\item Suppose $Y$ is locally closed in $X$. If $X$ is sober then so is $Y$.
\end{enumerate}

